function steps(H,last){const S=[];for(let i=1;i<H.length;i++){const p=H[i-1],c=H[i];if((c.t0+3600)>last+180)break;
  const up=RULE==="A"?c.c>p.h:(c.h>p.h&&c.c>p.c),dn=RULE==="A"?c.c<p.l:(c.l<p.l&&c.c<p.c);
  const r=ZR.rot[i]||0,ok=!ROT||r===0||(up&&r>0)||(dn&&r<0);if(up&&!dn)S.push({dir:1,px:p.h,t:c.t0+3600,hour:c.t0,ok});else if(dn&&!up)S.push({dir:-1,px:p.l,t:c.t0+3600,hour:c.t0,ok})}SKIP=S.filter(q=>!q.ok);return S.filter(q=>q.ok)}
function zigzag(B){const rng=B.reduce((a,b)=>a+(b[2]-b[3]),0)/B.length,th=2.5*rng,P=[];let dir=0,hi=B[0][2],hiI=0,lo=B[0][3],loI=0;
 for(let i=1;i<B.length;i++){const b=B[i];
  if(dir===0){if(b[2]>hi){hi=b[2];hiI=i}if(b[3]<lo){lo=b[3];loI=i}
   if(hi-b[3]>=th&&hiI<i){P.push([0,B[0][1]]);P.push([hiI,hi]);dir=-1;lo=b[3];loI=i}
   else if(b[2]-lo>=th&&loI<i){P.push([0,B[0][1]]);P.push([loI,lo]);dir=1;hi=b[2];hiI=i}}
  else if(dir>0){if(b[2]>hi){hi=b[2];hiI=i}if(hi-b[3]>=th&&hiI<i){P.push([hiI,hi]);dir=-1;lo=b[3];loI=i}}
  else{if(b[3]<lo){lo=b[3];loI=i}if(b[2]-lo>=th&&loI<i){P.push([loI,lo]);dir=1;hi=b[2];hiI=i}}}
 if(dir>0)P.push([hiI,hi]);else if(dir<0)P.push([loI,lo]);return P}
const out={};
for(const rule of ['A','B'])for(const rot of [true,false]){RULE=rule;ROT=rot;
 for(const K of Object.keys(D)){const B=D[K].bars;const HR=hours(B);ZR=hzz(HR);const S=steps(HR,B[B.length-1][0]);
  S.forEach(q=>{let o=null;B.forEach(b=>{if(b[0]<q.hour&&(q.dir>0?Math.abs(b[2]-q.px)<1e-9:Math.abs(b[3]-q.px)<1e-9))o=b[0]});q.o=o===null?q.t:o});
  S.forEach((q,i)=>{q.xe=null;if(i+1>=S.length)return;const nt=S[i+1].o;q.xe=-1;for(const b of B){if(b[0]>nt&&(q.dir>0?b[4]<q.px:b[4]>q.px)){q.xe=b[0];break}}});
  out[rule+(rot?1:0)+'|'+K]={steps:S,skipped:SKIP.length,rot:ZR.rot,P:ZR.P};}}
const fs=require('fs');fs.writeFileSync('tests_step/ref.json',JSON.stringify(out));
const dd={};for(const K of Object.keys(D))dd[K]=D[K];fs.writeFileSync('tests_step/data.json',JSON.stringify(dd));
for(const k of Object.keys(out))console.log(k,out[k].steps.length,out[k].skipped);
